// ---------- VI ----------
k.push(L.section("VI. Ablation, Case Study, and Controls"));
k.push(L.subsection("A. Ablation"));
k.push(...L.tableTitle("VII", "Ablation (seed 0, 5 folds, %; Section VI-A)"));
const abRows = [["fagi", "FAGI (full)"], ["fagi_no_guard", "− GNNGuard"], ["fagi_no_pgd", "− PGD training"], ["fagi_no_dp", "− DP-SGD"], ["gnn", "GNN baseline"]];
const ab1 = { fagi: "fagi", fagi_no_guard: "fagi_no_guard", fagi_no_pgd: "fagi_no_pgd", fagi_no_dp: "fagi_no_dp", gnn: "gnn" };
k.push(L.table(["Variant", "CICIDS clean", "ε=0.1", "ε=0.5", `ε=0.5, ${fprTxt} FPR`, "Hard clean", "Hard PGD"],
  abRows.map(([key, name]) => { const hk = key === "gnn" ? "gnn_nopayload" : key;
    return { bold: key === "fagi", cells: [name, pct(M(AB[key].clean), 2), pct(M(AB[key]["worst_recall_eps0.1"])), pct(M(AB[key]["worst_recall_eps0.5"])),
      pct(mf0(ab1[key], "0.5")), ABH[hk] ? pct(M(ABH[hk].clean)) : "—", ABH[hk] ? pct(M(ABH[hk].adv)) : "—"] }; }),
  [1150, 750, 650, 650, 800, 650, 650]));
k.push(L.caption("CICIDS recall is worst-case attack recall at the default threshold except where a false-positive rate is given. On the hard synthetic data the GNN baseline row has no payload score.", false));
const tw = (t) => `${t.wins_a} of ${t.n} folds`;
k.push(P(`At a matched ${fprTxt} false-positive rate, removing PGD training lowers worst-case recall at ε_{adv} = 0.5 from ${pct(mf0("fagi", "0.5"))}% to ${pct(mf0("fagi_no_pgd", "0.5"))}%, and the full model is ahead in ${FT0["fagi_vs_fagi_no_pgd_fixed_0.5"].wins_a} of ${FT0["fagi_vs_fagi_no_pgd_fixed_0.5"].n} folds; at ε_{adv} = 0.1 PGD training shows no fold-level benefit for the private model (${pct(mf0("fagi", "0.1"))}% and ${pct(mf0("fagi_no_pgd", "0.1"))}%, ahead in ${FT0["fagi_vs_fagi_no_pgd_fixed_0.1"].wins_a} of ${FT0["fagi_vs_fagi_no_pgd_fixed_0.1"].n} folds), so its benefit is a large-budget effect (at ε_{adv} = 0.5 and the default threshold, ${pct(M(AB.fagi["worst_recall_eps0.5"]))}% with PGD training and ${pct(M(AB.fagi_no_pgd["worst_recall_eps0.5"]))}% without). Removing GNNGuard leaves it at ${pct(mf0("fagi_no_guard", "0.5"))}% (the full model is ahead in ${FT0["fagi_vs_fagi_no_guard_fixed_0.5"].wins_a} of ${FT0["fagi_vs_fagi_no_guard_fixed_0.5"].n} folds, ${pv(FT0["fagi_vs_fagi_no_guard_fixed_0.5"].p)}). At the default threshold, removing it raises recall to ${pct(M(AB.fagi_no_guard["worst_recall_eps0.5"]))}% (${TA.fagi_vs_no_guard_w05.wins_b} of ${TA.fagi_vs_no_guard_w05.n} folds) at almost the same false-positive rate (${pct(M(FX0.fagi_no_guard.fpr_default), 2)}% against ${pct(M(FX0.fagi.fpr_default), 2)}%), and at the matched rate the gap is ${pp(Math.abs(mf0("fagi_no_guard", "0.5") - mf0("fagi", "0.5")), 0)} points. GNNGuard has no measurable effect on CICIDS2017 either way: the filter is recomputed on the perturbed features, and pruning edges to the perturbed node neither helps nor hurts measurably here. Removing DP-SGD raises clean accuracy from ${pct(M(AB.fagi.clean), 2)}% to ${pct(M(AB.fagi_no_dp.clean), 2)}% in every fold, and worst-case recall at ε_{adv} = 0.5 and a matched false-positive rate from ${pct(mf0("fagi", "0.5"))}% to ${pct(mf0("fagi_no_dp", "0.5"))}% (${pct(M(AB.fagi["worst_recall_eps0.5"]))}% and ${pct(M(AB.fagi_no_dp["worst_recall_eps0.5"]))}% at the default threshold). Adversarial training is the component that raises the graph detector's large-budget recall, to the level of the k-NN vote; DP buys a formal guarantee at a measurable cost in clean accuracy and robustness; GNNGuard does not earn its place in this pipeline on CICIDS2017. With five folds, the smallest attainable p is 0.0625, so these are fold counts, not significance claims.`));
k.push(L.subsection("B. Case Study: A Multi-Stage Campaign"));
const stages = [["schema_recon", "reconnaissance"], ["sql_injection", "injection"], ["lateral_movement", "lateral movement"], ["slow_exfiltration", "exfiltration"]];
const worstStage = stages.reduce((x, s) => (AH.fagi.per_type_detection[s[0]] < AH.fagi.per_type_detection[x[0]] ? s : x), stages[0]);
k.push(P(`A multi-stage campaign moves through reconnaissance, injection, lateral movement, and exfiltration, and the four synthetic attack types match these stages; the intrusions in CISA's advisory {cisa} show the reconnaissance, lateral-movement, and exfiltration stages in practice. On the hard generator, with all attack types in training, ${stages.map(([t, n]) => `${n} recall is ${pct(AH.rf.per_type_detection[t])}% for the random forest, ${pct(AH.gnn.per_type_detection[t])}% for the six-feature GNN, and ${pct(AH.fagi.per_type_detection[t])}% for FAGI`).join("; ")}. Under DP, FAGI is weakest at ${worstStage[1]}. This is a reading of synthetic per-type recall, not a replay of a real campaign.`));

